{"path":"firmware/esp32/src/drivers/motor_driver.h","content":"#pragma once

#include <Arduino.h>

enum MotorStatus {
    MOTOR_STATUS_IDLE = 0,
    MOTOR_STATUS_READY,
    MOTOR_STATUS_RUNNING,
    MOTOR_STATUS_FAULT,
    MOTOR_STATUS_DISABLED
};

struct MotorConfig {
    uint8_t motorId;
    float maxVelocity;
    float maxTorque;
    float kp;
    float ki;
    float kd;
    uint16_t encoderBits;
    float gearboxRatio;
    bool hasBrake;
    bool hasEncoder;
};

class IMotorDriver {
public:
    virtual ~IMotorDriver() = default;

    virtual bool init() = 0;
    virtual void deinit() = 0;

    virtual MotorStatus getStatus() = 0;
    virtual float getTemperature() = 0;
    virtual int32_t getPosition() = 0;
    virtual float getVelocity() = 0;
    virtual float getCurrent() = 0;

    virtual void setPosition(float target) = 0;
    virtual void setVelocity(float target) = 0;
    virtual void setTorque(float target) = 0;
    virtual void enable() = 0;
    virtual void disable() = 0;
    virtual void faultReset() = 0;

    virtual void setLimits(float maxVelocity, float maxTorque) = 0;
    virtual void setGains(float kp, float ki, float kd) = 0;
};
